26	// ─── Refund tier policy ──────────────────────────────────────────────────────
27	// >= 48h before start: 80% refund
28	// >= 24h and < 48h:    50% refund
29	// <  24h:              0% refund
30	//
31	// All money math is done in INTEGER CENTS to avoid binary-float rounding (e.g.
32	// 19.99 * 0.5 = 9.995). Stripe `refunds.create.amount` is also in integer cents.
33	export function computeRefund(totalPriceEur: number, hoursBeforeStart: number) {
34	  const totalCents = Math.round(totalPriceEur * 100);
35	  if (hoursBeforeStart >= 48) {
36	    const cents = Math.round(totalCents * 0.80);
37	    return { refundPercent: 80, refundAmount: cents / 100, refundCents: cents, refundable: true };
38	  }
39	  if (hoursBeforeStart >= 24) {
40	    const cents = Math.round(totalCents * 0.50);
41	    return { refundPercent: 50, refundAmount: cents / 100, refundCents: cents, refundable: true };
42	  }
43	  return { refundPercent: 0, refundAmount: 0, refundCents: 0, refundable: false };
44	}
