80	function toMin(t: string): number {
81	  const [h, m] = t.split(":").map(Number);
82	  return h * 60 + m;
83	}
84	
85	function slotsBetween(startTime: string, endTime: string): string[] {
86	  const start = toMin(startTime);
87	  const end = toMin(endTime);
88	  const result: string[] = [];
89	  for (let m = start; m < end; m += 30) {
90	    const h = Math.floor(m / 60);
91	    const min = m % 60;
92	    result.push(`${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
93	  }
94	  return result;
95	}
