120	    return;
121	  }
122	
123	  const userId = getCurrentUserId(req)!;
124	  const role = await getUserRole(userId);
125	
126	  const conditions = [];
127	  if (params.data.courtId != null) {
128	    conditions.push(eq(bookingsTable.courtId, params.data.courtId));
129	  }
130	  if (params.data.status) {
131	    conditions.push(eq(bookingsTable.status, params.data.status));
132	  }
133	  if (params.data.customerEmail) {
134	    conditions.push(eq(bookingsTable.customerEmail, params.data.customerEmail));
135	  }
136	
137	  let query = db
138	    .select({
139	      booking: bookingsTable,
