144	    .$dynamic();
145	
146	  if (role === "admin") {
147	    if (conditions.length > 0) {
148	      query = query.where(and(...conditions));
149	    }
150	  } else {
151	    // "My bookings" — always scoped to the authenticated booker, regardless of
152	    // role. Owners use GET /api/owner/bookings for the facility-wide view.
153	    conditions.push(eq(bookingsTable.bookerUserId, userId));
154	    query = query.where(and(...conditions));
