161	// POST /bookings — supports both authenticated bookers and guests.
162	// No requireAuth: if the caller has a Clerk session, we associate the booking with their userId.
163	// If not, we treat it as a guest booking (bookerUserId=null) and generate a managementToken
164	// so the guest can later view/cancel via /api/guest/bookings/:token.
165	router.post("/bookings", async (req, res): Promise<void> => {
166	  const parsed = CreateBookingBody.safeParse(req.body);
167	  if (!parsed.success) {
168	    console.error("[bookings] validation failed:", JSON.stringify(req.body), parsed.error.flatten());
169	    res.status(400).json({ error: parsed.error.message, details: parsed.error.flatten() });
170	    return;
171	  }
172	
173	  const recurringGroupId =
174	    typeof req.body?.recurringGroupId === "string" && req.body.recurringGroupId.length > 0
175	      ? req.body.recurringGroupId
176	      : null;
177	
178	  const d0 = parsed.data.date;
179	  const dateStr0 = `${d0.getUTCFullYear()}-${String(d0.getUTCMonth() + 1).padStart(2, "0")}-${String(d0.getUTCDate()).padStart(2, "0")}`;
180	  const dayOfWeek = new Date(dateStr0 + "T00:00:00").getDay();
181	  const reqStart = parsed.data.startTime;
182	  const reqEnd = parsed.data.endTime;
183	  const reqStartMin = toMin(reqStart);
184	  const reqEndMin = toMin(reqEnd);
185	
186	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, parsed.data.courtId));
187	  if (!court) {
188	    res.status(404).json({ error: "Court not found" });
189	    return;
190	  }
191	
192	  // ── Working hours validation ────────────────────────────────────────────────
193	  if (court.workingHours) {
194	    try {
195	      const wh = JSON.parse(court.workingHours) as Record<string, { open: string; close: string; closed: boolean }>;
196	      const dayConfig = wh[String(dayOfWeek)];
197	      if (dayConfig) {
198	        if (dayConfig.closed) {
199	          res.status(400).json({ error: "Court is closed on this day", code: "COURT_CLOSED" });
200	          return;
201	        }
202	        const openMin = toMin(dayConfig.open ?? "07:00");
203	        const closeMin = toMin(dayConfig.close ?? "22:00");
204	        if (reqStartMin < openMin || reqEndMin > closeMin) {
205	          res.status(400).json({ error: "Requested time is outside court working hours", code: "OUTSIDE_WORKING_HOURS" });
206	          return;
207	        }
208	      }
209	    } catch {
210	      // malformed workingHours JSON — skip validation, allow booking
211	    }
212	  }
213	
214	  // ── Compute server-side price using per-slot pricing (same logic as availability endpoint) ──
215	  // This can be done outside the transaction since pricing config is owner-managed, not concurrent.
216	  const pricingEntries = await db.select()
217	    .from(courtPricingTable)
218	    .where(and(
219	      eq(courtPricingTable.courtId, parsed.data.courtId),
220	      eq(courtPricingTable.dayOfWeek, dayOfWeek),
221	    ));
222	
223	  const pricingMap = new Map(pricingEntries.map(e => [e.startTime, Number(e.price)]));
224	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
225	
226	  const slots = slotsBetween(reqStart, reqEnd);
227	  let courtPrice = 0;
228	  for (const slotStart of slots) {
229	    courtPrice += pricingMap.has(slotStart) ? pricingMap.get(slotStart)! : defaultSlotPrice;
230	  }
231	
232	  const durationMinutes = reqEndMin - reqStartMin;
233	  const slotCount = Math.round(durationMinutes / 30);
234	  const bookerUserId = getCurrentUserId(req);
235	
236	  // ── Atomically check conflicts and insert within a serialized transaction ──
237	  // A PostgreSQL advisory lock (per court+date) blocks any concurrent booking attempt
238	  // for the same court on the same day, making the read-then-write conflict check atomic.
239	  class BookingConflictError extends Error {
240	    constructor(public readonly statusCode: number, public readonly body: any) {
241	      super("BookingConflict");
242	    }
243	  }
244	
245	  let booking: typeof bookingsTable.$inferSelect;
246	  try {
247	    booking = await db.transaction(async (tx) => {
248	      // Acquire exclusive advisory lock for this court+date combination.
249	      // Released automatically at end of transaction.
250	      const dateInt = parseInt(dateStr0.replace(/-/g, ""), 10);
251	      await tx.execute(sql`SELECT pg_advisory_xact_lock(${sql.raw(String(parsed.data.courtId))}::int, ${sql.raw(String(dateInt))}::int)`);
252	
253	      // ── Conflict check (inside lock) ──
254	      const [conflictingBookings, conflictingBlocked] = await Promise.all([
255	        tx.select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
256	          .from(bookingsTable)
257	          .where(and(
258	            eq(bookingsTable.courtId, parsed.data.courtId),
259	            eq(bookingsTable.date, dateStr0),
260	            or(
261	              eq(bookingsTable.status, "confirmed"),
262	              eq(bookingsTable.status, "blocked"),
263	              eq(bookingsTable.status, "awaiting_players"),
264	              and(
265	                eq(bookingsTable.status, "pending"),
266	                sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`
267	              )
268	            )
269	          )),
270	        tx.select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
271	          .from(courtBlockedSlotsTable)
272	          .where(and(
273	            eq(courtBlockedSlotsTable.courtId, parsed.data.courtId),
274	            eq(courtBlockedSlotsTable.date, dateStr0),
275	          )),
276	      ]);
277	
278	      for (const b of conflictingBookings) {
279	        const bStart = toMin(b.startTime);
280	        const bEnd = toMin(b.endTime);
281	        if (reqStartMin < bEnd && reqEndMin > bStart) {
282	          throw new BookingConflictError(409, { error: "Requested time slot is not available", code: "SLOT_UNAVAILABLE" });
283	        }
284	      }
285	
286	      for (const b of conflictingBlocked) {
287	        const bStart = toMin(b.startTime);
288	        const bEnd = toMin(b.endTime);
289	        if (reqStartMin < bEnd && reqEndMin > bStart) {
290	          throw new BookingConflictError(409, { error: "Requested time slot is blocked", code: "SLOT_BLOCKED" });
291	        }
292	      }
293	
294	      // ── Equipment availability (inside lock, same consistent snapshot) ──
295	      let equipmentCost = 0;
296	      let validatedRentedItems: string | null = null;
297	      if (parsed.data.rentedItems) {
298	        try {
299	          const clientItems: Array<{ name: string; quantity?: number }> = JSON.parse(parsed.data.rentedItems);
300	          const courtEquipment: Array<{ name: string; pricePerSlot?: number; pricePerBooking?: number; stock: number }> =
301	            court.rentableItems ? JSON.parse(court.rentableItems) : [];
302	
303	          const existingBookings = await tx
304	            .select({ rentedItems: bookingsTable.rentedItems, startTime: bookingsTable.startTime, endTime: bookingsTable.endTime, status: bookingsTable.status })
305	            .from(bookingsTable)
306	            .where(and(eq(bookingsTable.courtId, parsed.data.courtId), eq(bookingsTable.date, dateStr0)));
307	          const bookedQty: Record<string, number> = {};
308	          for (const b of existingBookings) {
309	            if (!b.rentedItems || b.status === "cancelled") continue;
310	            const bStart = toMin(b.startTime);
311	            const bEnd = toMin(b.endTime);
312	            if (bEnd <= reqStartMin || bStart >= reqEndMin) continue;
313	            const items: Array<{ name: string; quantity: number }> = JSON.parse(b.rentedItems);
314	            for (const item of items) {
315	              bookedQty[item.name] = (bookedQty[item.name] ?? 0) + item.quantity;
316	            }
317	          }
318	
319	          const serverValidated: Array<{ name: string; pricePerSlot: number; quantity: number }> = [];
320	          for (const ci of clientItems) {
321	            const canonical = courtEquipment.find(e => e.name === ci.name);
322	            if (!canonical) continue;
323	            const pricePerSlot = canonical.pricePerSlot ?? canonical.pricePerBooking ?? 0;
324	            const qty = Math.max(1, Math.min(Math.floor(ci.quantity ?? 1), 20));
325	            const alreadyBooked = bookedQty[ci.name] ?? 0;
326	            if (alreadyBooked + qty > canonical.stock) {
327	              throw new BookingConflictError(409, {
328	                error: `Įranga "${ci.name}" nebepasiekiama: likę ${Math.max(0, canonical.stock - alreadyBooked)} vnt.`,
329	                code: "EQUIPMENT_UNAVAILABLE",
330	                item: ci.name,
331	                available: Math.max(0, canonical.stock - alreadyBooked),
332	              });
333	            }
334	            serverValidated.push({ name: canonical.name, pricePerSlot, quantity: qty });
335	            equipmentCost += pricePerSlot * qty * slotCount;
336	          }
337	          if (serverValidated.length > 0) validatedRentedItems = JSON.stringify(serverValidated);
338	        } catch (e) {
339	          if (e instanceof BookingConflictError) throw e;
340	          console.error("[bookings] equipment validation error:", e);
341	        }
342	      }
343	
344	      const totalPrice = courtPrice + equipmentCost;
345	
346	      // ── Insert inside the same transaction ──
347	      // Guests (no Clerk session) get a management_token so they can later view & cancel
348	      // their booking via /api/guest/bookings/:token. Authenticated users use their session.
349	      const managementToken = bookerUserId ? null : generateManagementToken();
350	
351	      const [inserted] = await tx.insert(bookingsTable).values({
352	        courtId: parsed.data.courtId,
353	        bookerUserId: bookerUserId ?? null,
354	        customerName: parsed.data.customerName,
355	        customerEmail: parsed.data.customerEmail,
356	        customerPhone: parsed.data.customerPhone ?? null,
357	        date: dateStr0,
358	        startTime: parsed.data.startTime,
359	        endTime: parsed.data.endTime,
360	        totalPrice: String(totalPrice),
361	        rentedItems: validatedRentedItems,
362	        status: "pending",
363	        managementToken,
364	        recurringGroupId,
365	      }).returning();
366	
367	      return inserted;
368	    });
369	  } catch (err) {
370	    if (err instanceof BookingConflictError) {
371	      res.status(err.statusCode).json(err.body);
372	      return;
373	    }
374	    throw err;
375	  }
376	
377	  {
378	    const [bookingFacility] = await db.select({ ownerUserId: facilitiesTable.ownerUserId })
379	      .from(facilitiesTable).where(eq(facilitiesTable.id, court.facilityId));
380	    if (bookingFacility?.ownerUserId) {
381	      await sendNotification(
382	        bookingFacility.ownerUserId,
383	        "booking_created",
384	        `Nauja rezervacija — ${court.name}`,
385	        `${parsed.data.customerName} užrezervavo ${dateStr0} ${parsed.data.startTime}–${parsed.data.endTime}.`,
386	        "/owner",
387	      );
388	    }
389	  }
390	
391	  res.status(201).json(GetBookingResponse.parse(formatBooking(booking, court.name)));
392	});
