398	    return;
399	  }
400	
401	  const userId = getCurrentUserId(req)!;
402	
403	  const rows = await db
404	    .select({
405	      booking: bookingsTable,
406	      courtName: courtsTable.name,
407	      courtSport: courtsTable.type,
408	      facilityOwnerUserId: facilitiesTable.ownerUserId,
409	      facilityName: facilitiesTable.name,
410	      courtAddress: facilitiesTable.address,
411	      courtCity: facilitiesTable.city,
412	    })
413	    .from(bookingsTable)
414	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
415	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
416	    .where(eq(bookingsTable.id, params.data.id));
