442	router.delete("/bookings/:id", requireAuth, async (req, res): Promise<void> => {
443	  const params = CancelBookingParams.safeParse(req.params);
444	  if (!params.success) {
445	    res.status(400).json({ error: params.error.message });
446	    return;
447	  }
448	
449	  const userId = getCurrentUserId(req)!;
450	
451	  const rows = await db
452	    .select({
453	      booking: bookingsTable,
454	      courtName: courtsTable.name,
455	      facilityOwnerUserId: facilitiesTable.ownerUserId,
456	      facilityOwnerName: facilitiesTable.name,
457	      facilityOwnerEmail: facilitiesTable.email,
458	    })
459	    .from(bookingsTable)
460	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
461	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
462	    .where(eq(bookingsTable.id, params.data.id));
463	
464	  if (!rows[0]) {
465	    res.status(404).json({ error: "Booking not found" });
466	    return;
467	  }
468	
469	  const { booking, facilityOwnerUserId, courtName, facilityOwnerName: ownerName, facilityOwnerEmail: ownerEmail } = rows[0];
470	  const role = await getUserRole(userId);
471	  const isBooker = booking.bookerUserId === userId;
472	  const isCourtOwner = facilityOwnerUserId === userId;
473	
474	  if (role !== "admin" && !isBooker && !isCourtOwner) {
475	    res.status(403).json({ error: "Forbidden" });
476	    return;
477	  }
478	
479	  if (booking.status === "cancelled") {
480	    res.json(CancelBookingResponse.parse(formatBooking(booking)));
481	    return;
482	  }
483	
484	  // ─── Refund tier calculation ─────────────────────────────────────────────
485	  // Policy applies uniformly to all roles. No silent admin override.
486	  const totalPriceEur = Number(booking.totalPrice);
487	  const hours = hoursBeforeStart(booking.date, booking.startTime);
488	  const tier = computeRefund(totalPriceEur, hours);
489	
490	  // Prevent cancelling a booking that has already started/ended.
491	  if (hours <= 0) {
492	    res.status(400).json({ error: "Booking has already started or ended", code: "CANCEL_TOO_LATE" });
493	    return;
494	  }
495	
496	  // ─── Atomic compare-and-set on status to prevent double-refund ──────────
497	  // Only proceed if we successfully transitioned status from non-cancelled to cancelled.
498	  const claimed = await db
499	    .update(bookingsTable)
500	    .set({ status: "cancelled" })
501	    .where(and(eq(bookingsTable.id, params.data.id), ne(bookingsTable.status, "cancelled")))
502	    .returning();
503	
504	  if (claimed.length === 0) {
505	    // Another request beat us to it — return current state without issuing a refund.
506	    const [current] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, params.data.id));
507	    res.json(CancelBookingResponse.parse(formatBooking(current)));
508	    return;
509	  }
510	
511	  // ─── Issue Stripe refund if applicable ───────────────────────────────────
512	  let stripeRefundId: string | null = null;
513	  if (
514	    tier.refundable &&
515	    tier.refundAmount > 0 &&
516	    booking.stripePaymentIntentId &&
517	    !booking.stripePaymentIntentId.startsWith("mock_")
518	  ) {
519	    try {
520	      const stripe = await getUncachableStripeClient();
521	      const refund = await stripe.refunds.create(
522	        {
523	          payment_intent: booking.stripePaymentIntentId,
524	          amount: Math.round(tier.refundAmount * 100),
525	          reason: "requested_by_customer",
526	        },
527	        { idempotencyKey: `cancel-booking-${booking.id}` },
528	      );
529	      stripeRefundId = refund.id;
530	      logger.info(
