402	router.post("/payments/confirm-split", async (req, res): Promise<void> => {
403	  const sessionId = String(req.body?.sessionId ?? "");
404	  if (!sessionId) { res.status(400).json({ error: "sessionId required" }); return; }
405	
406	  // Find the booking (and court) by stripeSessionId
407	  const rows = await db
408	    .select({ booking: bookingsTable, court: courtsTable })
409	    .from(bookingsTable)
410	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
411	    .where(eq(bookingsTable.stripeSessionId, sessionId));
412	
413	  if (!rows[0]) { res.status(404).json({ error: "Booking not found for session" }); return; }
414	  const { booking, court } = rows[0];
415	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
416	
417	  // Verify Stripe payment and read metadata (skip for mocks)
418	  let linkGameId: number | null = null;
419	  if (!sessionId.startsWith("mock_")) {
420	    try {
421	      const stripe = await getUncachableStripeClient();
422	      const session = await stripe.checkout.sessions.retrieve(sessionId);
423	      if (session.payment_status !== "paid") {
424	        res.status(402).json({ error: "Payment not completed" });
425	        return;
426	      }
427	      const lgId = session.metadata?.linkGameId;
428	      if (lgId) linkGameId = parseInt(lgId, 10);
429	    } catch (err) {
430	      logger.error({ err }, "Stripe retrieve session error in confirm-split");
431	    }
432	  }
433	
434	  // Find participant by stripeSessionId → mark as paid (idempotent)
435	  const [participant] = await db
436	    .select()
437	    .from(gameParticipantsTable)
438	    .where(eq(gameParticipantsTable.stripeSessionId, sessionId));
439	
440	  if (participant && participant.paymentStatus !== "paid") {
441	    await db
442	      .update(gameParticipantsTable)
443	      .set({ paymentStatus: "paid" })
444	      .where(eq(gameParticipantsTable.id, participant.id));
445	  }
446	
447	  // Move booking to awaiting_players (from pending) — track if this is a fresh transition
448	  let justTransitioned = false;
449	  if (booking.status === "pending") {
450	    const updated = await db
451	      .update(bookingsTable)
452	      .set({ status: "awaiting_players" })
453	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")))
454	      .returning();
455	    justTransitioned = updated.length > 0;
456	  }
457	
458	  // Find linked game and transition it
459	  let game: typeof gamesTable.$inferSelect | undefined;
460	  if (linkGameId) {
461	    // Upgrade flow: update the pre-existing casual game
462	    const [courtRow] = await db
463	      .select({ facilityId: facilitiesTable.id, courtId: courtsTable.id })
464	      .from(courtsTable)
465	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
466	      .where(eq(courtsTable.id, booking.courtId));
467	    await db
468	      .update(gamesTable)
469	      .set({
470	        bookingId: booking.id,
471	        facilityId: courtRow?.facilityId ?? null,
472	        courtId: courtRow?.courtId ?? booking.courtId,
473	        status: "awaiting_players",
474	        datetime: `${booking.date}T${booking.startTime}:00`,
475	        durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
476	      })
477	      .where(eq(gamesTable.id, linkGameId));
478	    const [updated] = await db.select().from(gamesTable).where(eq(gamesTable.id, linkGameId));
479	    game = updated;
480	  } else {
481	    // Normal flow: find the game that was created alongside this booking
482	    const [found] = await db
483	      .select()
484	      .from(gamesTable)
485	      .where(eq(gamesTable.bookingId, booking.id));
486	    if (found && found.status === "pending_payment") {
487	      await db
488	        .update(gamesTable)
489	        .set({ status: "awaiting_players" })
490	        .where(and(eq(gamesTable.id, found.id), eq(gamesTable.status, "pending_payment")));
491	    }
492	    game = found;
493	  }
494	
495	  // Aggregate paid participant count
496	  const allParticipants = game
497	    ? await db
498	        .select({ paymentStatus: gameParticipantsTable.paymentStatus })
499	        .from(gameParticipantsTable)
500	        .where(and(
501	          eq(gameParticipantsTable.gameId, game.id),
502	          eq(gameParticipantsTable.status, "joined"),
503	        ))
504	    : [];
505	  const paidSlots = allParticipants.filter(p => p.paymentStatus === "paid").length;
506	
507	  // Send email + notification to host if this was a fresh game creation
508	  if (justTransitioned && booking.bookerUserId && booking.splitInviteToken) {
509	    const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
510	    const base = process.env.BASE_PATH ?? "";
511	    const shareLink = `${origin}${base}/join/${booking.splitInviteToken}`;
512	
513	    sendSplitBookingCreatedEmail({
514	      hostName: booking.customerName,
515	      hostEmail: booking.customerEmail,
516	      courtName: court?.name ?? "Kortas",
517	      courtId: booking.courtId,
518	      date: booking.date,
519	      startTime: booking.startTime,
520	      endTime: booking.endTime,
521	      pricePerSlot: Number(booking.pricePerSlot ?? 0),
522	      totalPrice: Number(booking.totalPrice),
523	      totalSlots: booking.totalSlots ?? 1,
524	      shareLink,
525	      bookingId: booking.id,
526	    }).catch((err) => logger.error({ err }, "sendSplitBookingCreatedEmail failed"));
527	
528	    sendNotification(
529	      booking.bookerUserId,
530	      "split_player_joined",
531	      "Žaidimas sukurtas!",
532	      `Jūsų vieta aikštelėje ${court?.name ?? "kortas"} (${booking.date}) patvirtinta. Dalinkitės nuoroda su žaidėjais.`,
533	      `/bookings/${booking.id}`,
534	    ).catch(() => {});
535	  }
536	
537	  res.json({
538	    bookingId: booking.id,
539	    gameId: game?.id ?? null,
540	    shareToken: booking.splitInviteToken ?? null,
541	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
542	    totalSlots: booking.totalSlots ?? 1,
543	    paidSlots,
