547	    endTime: booking.endTime,
548	    sport: game?.sport ?? null,
549	    isPublic: game?.visibility === "public",
550	    courtId: booking.courtId,
551	    courtName: court?.name ?? null,
552	    courtImageUrl: court?.imageUrl ?? null,
553	  });
554	});
