535	router.delete("/games/:id", requireAuth, async (req, res): Promise<void> => {
536	  const id = parseInt(String(req.params.id), 10);
537	  const userId = getCurrentUserId(req)!;
538	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
539	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
540	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
541	
542	  // ─── Single-owner cancellation claim ─────────────────────────────────────────
543	  // CAS the game into 'cancelling' so that concurrent DELETEs are rejected with 409.
544	  // Without this, a second request could race past the booking-CAS (which would
545	  // already be claimed) and delete the game while the first request's Stripe call
546	  // is still in flight, producing "game deleted but booking still confirmed and
547	  // no refund issued" if Stripe then fails and the first request rolls booking back.
548	  const originalStatus = g.status;
549	  const claimGame = await db
550	    .update(gamesTable)
551	    .set({ status: "cancelling" })
552	    .where(and(eq(gamesTable.id, id), ne(gamesTable.status, "cancelling")))
553	    .returning();
554	  if (claimGame.length === 0) {
555	    res.status(409).json({ error: "Atšaukimas jau vykdomas. Bandykite po akimirkos." });
556	    return;
557	  }
558	
559	  // ─── If a paid Korts.lt booking is linked, mirror the standard booking-cancel + refund flow ──
560	  let refundedAmount = 0;
561	  let refundPercent = 0;
562	  if (g.bookingId) {
563	    const [booking] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, g.bookingId));
564	    if (booking && booking.status !== "cancelled") {
565	      const totalPriceEur = Number(booking.totalPrice);
566	      const hours = hoursBeforeStart(booking.date, booking.startTime);
567	      if (hours <= 0) {
568	        res.status(400).json({ error: "Žaidimas jau prasidėjo arba pasibaigė", code: "CANCEL_TOO_LATE" });
569	        return;
570	      }
571	      const tier = computeRefund(totalPriceEur, hours);
572	
573	      // CAS on booking status to prevent double-refund if the host clicks twice or the
574	      // sweeper races us on a still-pending booking.
575	      const claimed = await db
576	        .update(bookingsTable)
577	        .set({ status: "cancelled" })
578	        .where(and(eq(bookingsTable.id, booking.id), ne(bookingsTable.status, "cancelled")))
579	        .returning();
580	
581	      if (claimed.length > 0) {
582	        let stripeRefundId: string | null = null;
583	        if (
584	          tier.refundable &&
585	          tier.refundAmount > 0 &&
586	          booking.stripePaymentIntentId &&
587	          !booking.stripePaymentIntentId.startsWith("mock_")
588	        ) {
589	          try {
590	            const stripe = await getUncachableStripeClient();
591	            const refund = await stripe.refunds.create(
592	              {
593	                payment_intent: booking.stripePaymentIntentId,
594	                amount: Math.round(tier.refundAmount * 100),
595	                reason: "requested_by_customer",
596	              },
597	              { idempotencyKey: `cancel-game-${g.id}` },
598	            );
599	            stripeRefundId = refund.id;
600	            logger.info(
601	              { gameId: g.id, bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount },
602	              "Stripe refund issued for host-cancelled game",
603	            );
604	          } catch (err) {
605	            logger.error({ err, gameId: g.id, bookingId: booking.id }, "Stripe refund failed");
606	            // Roll back BOTH booking and game status so the host can retry.
607	            // Without restoring game.status, the next attempt would 409 forever.
608	            await db
609	              .update(bookingsTable)
610	              .set({ status: booking.status })
611	              .where(eq(bookingsTable.id, booking.id));
612	            await db
613	              .update(gamesTable)
614	              .set({ status: originalStatus })
615	              .where(eq(gamesTable.id, g.id));
616	            res.status(502).json({ error: "Nepavyko grąžinti pinigų. Bandykite dar kartą." });
617	            return;
618	          }
619	        }
620	
621	        await db
622	          .update(bookingsTable)
623	          .set({ refundAmount: String(tier.refundAmount), stripeRefundId })
624	          .where(eq(bookingsTable.id, booking.id));
625	
626	        refundedAmount = tier.refundAmount;
627	        refundPercent = tier.refundPercent;
628	      }
629	    }
630	  }
631	
632	  // Collect all participants before deleting (except creator) so we can notify them.
633	  const participants = await db
634	    .select()
635	    .from(gameParticipantsTable)
636	    .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "joined")));
637	
638	  // bookingId on games has ON DELETE SET NULL, so the booking row (now 'cancelled')
639	  // survives for refund history; participants/results/chat cascade-delete with the game.
640	  await db.delete(gamesTable).where(eq(gamesTable.id, id));
641	
642	  // Notify all joined participants that the host cancelled.
643	  const sportLabel = g.sport.replace(/_/g, " ");
644	  const gameDate = new Date(g.datetime).toLocaleDateString("lt-LT");
645	  for (const p of participants) {
646	    if (p.userId && p.userId !== userId) {
647	      await sendNotification(
648	        p.userId,
649	        "game_cancelled",
650	        "Žaidimas atšauktas",
651	        `${sportLabel} žaidimas ${gameDate} (${g.city}) buvo atšauktas organizatoriaus.`,
652	        "/matches",
653	      );
654	    }
655	  }
656	
657	  res.json({ ok: true, refundAmount: refundedAmount, refundPercent });
658	});
