1630	export async function applyResultElo(gameResultId: number): Promise<void> {
1631	  const [result] = await db.select().from(gameResultsTable).where(eq(gameResultsTable.id, gameResultId));
1632	  if (!result) return;
1633	  if (result.status === "confirmed") return; // idempotent
1634	
1635	  // Only the FIRST caller flips status (race between /verify-confirm and cron).
1636	  const flipped = await db
1637	    .update(gameResultsTable)
1638	    .set({ status: "confirmed" })
1639	    .where(and(eq(gameResultsTable.id, gameResultId), eq(gameResultsTable.status, "pending_verification")))
1640	    .returning();
1641	  if (flipped.length === 0) return; // somebody else already promoted
1642	
1643	  await db.update(gamesTable).set({ status: "completed" }).where(eq(gamesTable.id, result.gameId));
1644	
1645	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, result.gameId));
1646	  if (!g || g.matchType !== "rated") return;
1647	
1648	  const participants = await db.select().from(gameParticipantsTable)
1649	    .where(and(eq(gameParticipantsTable.gameId, g.id), eq(gameParticipantsTable.status, "joined")));
1650	  const teamAPlayers = participants.filter(p => p.team === "A");
1651	  const teamBPlayers = participants.filter(p => p.team === "B");
1652	  const unassigned = participants.filter(p => !p.team);
1653	  const effectiveTeamA = teamAPlayers.length ? teamAPlayers : unassigned.slice(0, Math.ceil(unassigned.length / 2));
1654	  const effectiveTeamB = teamBPlayers.length ? teamBPlayers : unassigned.slice(Math.ceil(unassigned.length / 2));
1655	
1656	  const teamAWithElo = await Promise.all(
1657	    effectiveTeamA.filter(p => p.userId !== null).map(async p => ({ userId: p.userId!, elo: (await getOrCreateRating(p.userId!, g.sport)).elo }))
1658	  );
1659	  const teamBWithElo = await Promise.all(
1660	    effectiveTeamB.filter(p => p.userId !== null).map(async p => ({ userId: p.userId!, elo: (await getOrCreateRating(p.userId!, g.sport)).elo }))
1661	  );
1662	
1663	  const winner: "A" | "B" | "draw" =
1664	    result.scoreTeamA > result.scoreTeamB ? "A" :
1665	    result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
1666	  const changes = calculateTeamElo(teamAWithElo, teamBWithElo, winner);
1667	  const isDraw = winner === "draw";
1668	
1669	  for (const change of changes) {
1670	    const isOnTeamA = !!teamAWithElo.find(p => p.userId === change.userId);
1671	    const isWinner = isDraw ? false : (isOnTeamA ? winner === "A" : winner === "B");
1672	    const winsAdd = isDraw ? 0 : (isWinner ? 1 : 0);
1673	    const lossesAdd = isDraw ? 0 : (!isWinner ? 1 : 0);
1674	    const drawsAdd = isDraw ? 1 : 0;
1675	
1676	    await db.update(userRatingsTable)
1677	      .set({
1678	        elo: change.newElo,
1679	        wins: sql`${userRatingsTable.wins} + ${winsAdd}`,
1680	        losses: sql`${userRatingsTable.losses} + ${lossesAdd}`,
1681	        draws: sql`${userRatingsTable.draws} + ${drawsAdd}`,
1682	        updatedAt: new Date(),
1683	      })
1684	      .where(and(eq(userRatingsTable.userId, change.userId), eq(userRatingsTable.sportSlug, g.sport)));
1685	
1686	    await db.insert(eloHistoryTable).values({
1687	      userId: change.userId,
1688	      sportSlug: g.sport,
1689	      elo: change.newElo,
