62	const ForceCancelBody = z.object({
63	  refundAmountCents: z.number().int().min(0),
64	});
65	
66	/**
67	 * POST /api/owner/bookings/:id/force-cancel
68	 *
69	 * Owner manual override. Bypasses the 24h/48h cancellation policy and accepts
70	 * a custom refund amount in cents (0..totalPriceCents). Requires the caller to
71	 * own the court (directly via courts.ownerUserId, or transitively via the
72	 * facility's ownerUserId).
73	 *
74	 * Mirrors DELETE /bookings/:id but with no time restriction and a caller-supplied
75	 * refund amount. Issues a Stripe refund (idempotent, distinct key from the regular
76	 * cancel) and frees the timeslot by transitioning status to "cancelled".
77	 */
78	router.post("/owner/bookings/:id/force-cancel", requireAuth, async (req, res): Promise<void> => {
79	  const id = Number(req.params.id);
80	  if (!Number.isInteger(id) || id <= 0) {
81	    res.status(400).json({ error: "Invalid booking id" });
82	    return;
83	  }
84	
85	  const parsed = ForceCancelBody.safeParse(req.body);
86	  if (!parsed.success) {
87	    res.status(400).json({ error: parsed.error.message });
88	    return;
89	  }
90	
91	  const userId = getCurrentUserId(req)!;
92	
93	  const rows = await db
94	    .select({
95	      booking: bookingsTable,
96	      courtOwnerUserId: facilitiesTable.ownerUserId,
97	      courtFacilityId: courtsTable.facilityId,
98	      courtName: courtsTable.name,
99	      ownerName: facilitiesTable.name,
100	      ownerEmail: facilitiesTable.email,
101	    })
102	    .from(bookingsTable)
103	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
104	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
105	    .where(eq(bookingsTable.id, id));
106	
107	  if (!rows[0]) {
108	    res.status(404).json({ error: "Booking not found" });
109	    return;
110	  }
111	
112	  const { booking, courtOwnerUserId, courtFacilityId, courtName, ownerName, ownerEmail } = rows[0];
113	
114	  // Ownership check: caller must own the facility.
115	  const isOwner = courtOwnerUserId === userId;
116	  if (!isOwner) {
117	    res.status(403).json({ error: "Forbidden" });
118	    return;
119	  }
120	
121	  if (booking.status === "cancelled") {
122	    res.status(409).json({ error: "Booking is already cancelled" });
123	    return;
124	  }
125	
126	  // Validate refund amount: must not exceed the original totalPrice.
127	  const totalPriceEur = Number(booking.totalPrice);
128	  const totalPriceCents = Math.round(totalPriceEur * 100);
129	  const refundCents = parsed.data.refundAmountCents;
130	  if (refundCents > totalPriceCents) {
131	    res.status(400).json({
132	      error: `Refund amount (${(refundCents / 100).toFixed(2)} €) exceeds booking total (${totalPriceEur.toFixed(2)} €)`,
133	      code: "REFUND_EXCEEDS_TOTAL",
134	    });
135	    return;
136	  }
137	  const refundEur = refundCents / 100;
138	
139	  // Atomic compare-and-set on status to prevent double-refund races with the
140	  // regular cancel route.
141	  const claimed = await db
142	    .update(bookingsTable)
143	    .set({ status: "cancelled" })
144	    .where(and(eq(bookingsTable.id, id), ne(bookingsTable.status, "cancelled")))
145	    .returning();
146	
147	  if (claimed.length === 0) {
148	    const [current] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, id));
149	    res.json({
150	      id: current.id,
151	      status: current.status,
152	      refundAmount: Number(current.refundAmount ?? 0),
153	    });
154	    return;
155	  }
156	
157	  // Issue Stripe refund if applicable. Use a distinct idempotency key from the
158	  // regular cancel route so an owner override after a customer self-cancel
159	  // doesn't get suppressed by Stripe's idempotency cache.
160	  let stripeRefundId: string | null = null;
161	  if (
162	    refundCents > 0 &&
163	    booking.stripePaymentIntentId &&
164	    !booking.stripePaymentIntentId.startsWith("mock_")
165	  ) {
166	    try {
167	      const stripe = await getUncachableStripeClient();
168	      const refund = await stripe.refunds.create(
169	        {
170	          payment_intent: booking.stripePaymentIntentId,
171	          amount: refundCents,
172	          reason: "requested_by_customer",
173	        },
174	        { idempotencyKey: `force-cancel-booking-${id}` },
175	      );
176	      stripeRefundId = refund.id;
177	      logger.info(
178	        { bookingId: id, refundId: refund.id, amount: refundEur, actor: userId },
179	        "Stripe force-cancel refund issued",
180	      );
181	    } catch (err) {
182	      logger.error({ err, bookingId: id }, "Stripe force-cancel refund failed");
183	      await db
184	        .update(bookingsTable)
185	        .set({ status: booking.status })
186	        .where(eq(bookingsTable.id, id));
187	      res.status(502).json({ error: "Refund failed at payment provider" });
188	      return;
189	    }
190	  }
191	
192	  const [updated] = await db
193	    .update(bookingsTable)
194	    .set({
195	      refundAmount: String(refundEur),
196	      stripeRefundId,
197	    })
198	    .where(eq(bookingsTable.id, id))
199	    .returning();
200	
201	  // Notifications (fire-and-forget, never block the response).
202	  const displayCourtName = courtName ?? "Kortas";
203	  const dateStr = typeof booking.date === "string" ? booking.date : String(booking.date);
204	
205	  // Notify the booker (unless the owner force-cancelled their own booking).
206	  if (booking.bookerUserId && booking.bookerUserId !== userId) {
207	    sendNotification(
208	      booking.bookerUserId,
209	      "booking_cancelled",
210	      `Rezervacija atšaukta — ${displayCourtName}`,
211	      refundEur > 0
212	        ? `Jūsų rezervacija ${dateStr} ${booking.startTime}–${booking.endTime} atšaukta savininko. Grąžinta: ${refundEur.toFixed(2)} €.`
213	        : `Jūsų rezervacija ${dateStr} ${booking.startTime}–${booking.endTime} atšaukta savininko.`,
214	      "/bookings",
215	    ).catch((err) => logger.error({ err, bookingId: id }, "force-cancel booker notification failed"));
216	  }
217	
218	  // Email customer with refund details.
219	  if (booking.customerEmail) {
220	    sendCustomerCancellationEmail({
221	      customerName: booking.customerName,
222	      customerEmail: booking.customerEmail,
223	      courtName: displayCourtName,
224	      date: booking.date,
225	      startTime: booking.startTime,
226	      endTime: booking.endTime,
227	      totalPrice: totalPriceEur,
228	      refundAmount: refundEur,
229	      bookingId: id,
230	    }).catch((err) => logger.error({ err, bookingId: id }, "force-cancel customer email failed"));
231	  }
232	
233	  // No notification/email to the owner — they triggered this themselves.
234	  // Reference ownerName/ownerEmail to satisfy noUnusedLocals while preserving
235	  // them in the join (also lets us log who the owner was for audit).
236	  void ownerName;
237	  void ownerEmail;
238	
239	  res.json({
240	    id: updated.id,
241	    status: updated.status,
242	    refundAmount: Number(updated.refundAmount ?? 0),
243	    stripeRefundId: updated.stripeRefundId ?? null,
244	  });
245	});
