3	import { logger } from "./logger";
4	
5	const TICK_INTERVAL_MS = 60 * 1000;
6	
7	export function startCron(): void {
8	  let running = false;
9	  const tick = async () => {
10	    if (running) return;
11	    running = true;
12	    try {
13	      const [staleCount, autoCount, abandonedBookingCount] = await Promise.all([
14	        sweepStalePendingGames(),
15	        sweepAutoConfirmResults(),
16	        sweepAbandonedPendingBookings(),
17	      ]);
18	      if (staleCount > 0 || autoCount > 0 || abandonedBookingCount > 0) {
19	        logger.info({ staleCount, autoCount, abandonedBookingCount }, "cron: swept");
20	      }
21	    } catch (err) {
22	      logger.error({ err }, "cron tick failed");
23	    } finally {
24	      running = false;
25	    }
26	  };
27	  setInterval(tick, TICK_INTERVAL_MS);
28	  setTimeout(tick, 5000);
29	  logger.info({ intervalMs: TICK_INTERVAL_MS }, "cron started");
30	}
