1	import type { Request, Response, NextFunction } from "express";
2	import { getAuth, clerkClient } from "@clerk/express";
3	import { db } from "@workspace/db";
4	import { userRolesTable } from "@workspace/db/schema";
5	import { eq } from "drizzle-orm";
6	import { timingSafeEqual } from "node:crypto";
7	import type { UserRole } from "@workspace/db/schema";
8	
9	/**
10	 * Test-only auth bypass. If AGENT_BYPASS_KEY is set in env AND a request carries
11	 * `x-replit-agent-auth: <that key>`, requireAuth/requireOwner/requireCoach/
12	 * requireAdmin all let the request through. The caller can also provide:
13	 *   x-replit-agent-userid: <clerk-user-id>   (the userId getCurrentUserId returns)
14	 *   x-replit-agent-role:   <admin|owner|coach|player>   (the role getUserRole returns)
15	 * If those headers are omitted, defaults are 'agent-test-user' and 'admin'.
16	 *
17	 * The bypass is a no-op when AGENT_BYPASS_KEY is unset, so production safety is
18	 * preserved as long as that secret is never set in the production environment.
19	 */
20	function isAgentBypass(req: Request): boolean {
21	  const expected = process.env.AGENT_BYPASS_KEY;
22	  if (!expected) return false;
23	  const provided = req.header("x-replit-agent-auth");
24	  if (!provided) return false;
25	  const a = Buffer.from(expected);
26	  const b = Buffer.from(provided);
27	  if (a.length !== b.length) return false;
28	  return timingSafeEqual(a, b);
29	}
30	
31	function bypassUserId(req: Request): string {
32	  return req.header("x-replit-agent-userid") || "agent-test-user";
33	}
34	
35	function bypassRole(req: Request): UserRole {
36	  const r = req.header("x-replit-agent-role");
37	  if (r === "admin" || r === "owner" || r === "coach" || r === "player") return r;
38	  return "admin";
39	}
40	
41	/**
42	 * Inject the bypass userId into Clerk's request-scoped auth so downstream
43	 * `getAuth(req).userId` calls return the synthetic id rather than null.
44	 * Safe to call multiple times — it just overwrites req.auth.
45	 */
46	function applyBypassToReq(req: Request): void {
47	  const userId = bypassUserId(req);
48	  // In @clerk/express v2, getAuth(req) calls `req.auth(options)` and then runs
49	  // it through getAuthObjectForAcceptedToken which strips userId to null unless
50	  // tokenType matches the accepted set ("session_token" by default). So we must
51	  // mimic the shape of signedInAuthObject from @clerk/backend.
52	  const authState = {
53	    tokenType: "session_token",
54	    userId,
55	    sessionId: "agent-bypass-session",
56	    sessionStatus: "active",
57	    sessionClaims: { sub: userId, iss: "agent-bypass", sid: "agent-bypass-session" },
58	    orgId: null,
59	    orgRole: null,
60	    orgSlug: null,
61	    orgPermissions: null,
62	    factorVerificationAge: null,
63	    actor: null,
64	    isAuthenticated: true,
65	    has: () => false,
66	    debug: () => ({}),
67	    getToken: async () => null,
68	  };
69	  // clerkMiddleware sets req.auth via Object.defineProperty, so we must
70	  // redefine the property to override it.
71	  Object.defineProperty(req, "auth", {
72	    configurable: true,
73	    enumerable: true,
74	    writable: true,
75	    value: () => authState,
76	  });
77	}
78	
79	/** IDs in ADMIN_USER_IDS env var always get admin role, even if DB says otherwise */
80	const HARDCODED_ADMIN_IDS = new Set(
81	  (process.env.ADMIN_USER_IDS ?? "").split(",").map(s => s.trim()).filter(Boolean)
82	);
83	
84	/** Emails in ADMIN_EMAILS env var always get admin role, regardless of Clerk user_id.
85	 *  Anchored to email (stable) rather than user_id (changes if account is recreated). */
86	const HARDCODED_ADMIN_EMAILS = new Set(
87	  (process.env.ADMIN_EMAILS ?? "").split(",").map(s => s.trim().toLowerCase()).filter(Boolean)
88	);
89	
90	/** Cache email lookups briefly to avoid hammering Clerk on every request */
91	const emailCache = new Map<string, { email: string | null; expires: number }>();
92	const EMAIL_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
93	
94	async function getUserEmail(userId: string): Promise<string | null> {
95	  const cached = emailCache.get(userId);
96	  if (cached && cached.expires > Date.now()) return cached.email;
97	  try {
98	    const u = await clerkClient.users.getUser(userId);
99	    const email = u.emailAddresses?.[0]?.emailAddress?.toLowerCase() ?? null;
100	    emailCache.set(userId, { email, expires: Date.now() + EMAIL_CACHE_TTL_MS });
101	    return email;
102	  } catch {
103	    return null;
104	  }
105	}
106	
107	/** Fetch a user's role from DB; returns 'player' if no row exists.
108	 *  Users in ADMIN_USER_IDS or whose email is in ADMIN_EMAILS always get 'admin'. */
109	export async function getUserRole(userId: string): Promise<UserRole> {
110	  // The agent test bypass uses the synthetic 'agent-test-user' id.
111	  if (userId === "agent-test-user") return "admin";
112	  if (HARDCODED_ADMIN_IDS.has(userId)) return "admin";
113	  if (HARDCODED_ADMIN_EMAILS.size > 0) {
114	    const email = await getUserEmail(userId);
115	    if (email && HARDCODED_ADMIN_EMAILS.has(email)) return "admin";
116	  }
117	  const [row] = await db
118	    .select({ role: userRolesTable.role })
119	    .from(userRolesTable)
120	    .where(eq(userRolesTable.userId, userId));
121	  return (row?.role as UserRole) ?? "player";
122	}
123	
124	/** Ensure user has a role row (upsert as player on first visit) */
125	export async function ensureUserRole(userId: string): Promise<UserRole> {
126	  await db
127	    .insert(userRolesTable)
128	    .values({ userId, role: "player" })
129	    .onConflictDoNothing();
130	  return getUserRole(userId);
131	}
