144	/** Express middleware: requires role === 'admin' in user_roles table */
145	export async function requireAdmin(req: Request, res: Response, next: NextFunction): Promise<void> {
146	  try {
147	    if (isAgentBypass(req)) {
148	      if (bypassRole(req) === "admin") { applyBypassToReq(req); next(); return; }
149	      res.status(403).json({ error: "Forbidden – admin only (bypass role mismatch)" });
150	      return;
151	    }
152	    const { userId } = getAuth(req);
153	    if (!userId) {
154	      res.status(401).json({ error: "Unauthorized" });
155	      return;
156	    }
157	    const role = await getUserRole(userId);
158	    if (role !== "admin") {
159	      res.status(403).json({ error: "Forbidden – admin only" });
160	      return;
161	    }
162	    next();
163	  } catch (err) {
164	    next(err);
165	  }
166	}
