168	/** Express middleware: requires role === 'admin' or 'owner' */
169	export async function requireOwner(req: Request, res: Response, next: NextFunction): Promise<void> {
170	  try {
171	    if (isAgentBypass(req)) {
172	      const r = bypassRole(req);
173	      if (r === "admin" || r === "owner") { applyBypassToReq(req); next(); return; }
174	      res.status(403).json({ error: "Forbidden – owner or admin only (bypass role mismatch)" });
175	      return;
176	    }
177	    const { userId } = getAuth(req);
178	    if (!userId) {
179	      res.status(401).json({ error: "Unauthorized" });
180	      return;
181	    }
182	    const role = await getUserRole(userId);
183	    if (role !== "admin" && role !== "owner") {
184	      res.status(403).json({ error: "Forbidden – owner or admin only" });
185	      return;
186	    }
187	    next();
188	  } catch (err) {
189	    next(err);
190	  }
191	}
